// MODULES //

// In C, we replace stdlib's evalpoly with our own static helpers based on the JS files.
// We also translate all other helper functions.

// From: evalpoly/lib/main.js (Horner's method)
static double evalpoly( const double *c, const int len, const double x ) {
    double p;
    int i;

    if ( len < 2 || x == 0.0 ) {
        if ( len == 0 ) {
            return 0.0;
        }
        return c[ 0 ];
    }
    i = len - 1;
    p = ( c[ i ] * x ) + c[ i - 1 ];
    i -= 2;
    while ( i >= 0 ) {
        p = ( p * x ) + c[ i ];
        i -= 1;
    }
    return p;
}

// From: polyval_ak1.js
static double polyval_ak1( const double x ) {
    if ( x == 0.0 ) {
        return 0.0;
    }
    // return 0.0 + (x * (1.0 + (x * (1.0 + (x * (1.5 + (x * (2.6666666666666665 + (x * (5.208333333333333 + (x * 10.8)))))))))));
    static const double C[] = {
        0.0,
        1.0,
        1.0,
        1.5,
        2.6666666666666665,
        5.208333333333333,
        10.8
    };
    return evalpoly( C, 7, x );
}

// From: polyval_ak2.js
static double polyval_ak2( const double x ) {
    if ( x == 0.0 ) {
        return 1.0;
    }
    // return 1.0 + (x * (1.0 + (x * (0.3333333333333333 + (x * (0.027777777777777776 + (x * (-0.003703703703703704 + (x * (0.0002314814814814815 + (x * 0.00005878894767783657)))))))))));
    static const double C[] = {
        1.0,
        1.0,
        0.3333333333333333,
        0.027777777777777776,
        -0.003703703703703704,
        0.0002314814814814815,
        0.00005878894767783657
    };
    return evalpoly( C, 7, x );
}

